fn doc()->web_sys::Document{web_sys::window().unwrap().document().unwrap()}fn el(id:&str)->Element{doc().get_element_by_id(id).unwrap()}fn html(id:&str,value:&str){if input::holds(&el(id)){return}let changed=HTML_CACHE.with(|cache|{let mut cache=cache.borrow_mut();if cache.get(id).is_some_and(|old|old==value){false}else{cache.insert(id.into(),value.into());true}});if changed{let root=el(id);let expanded=|selector:&str|root.query_selector(selector).ok().flatten().is_some_and(|e|e.has_attribute("open"));let millwork_open=expanded(".millwork-controls");let library_open=expanded(".millwork-library");let source_open=expanded(".source-card");let colors_open=expanded("[data-section=colors]");let roof_open=expanded("[data-section=roof]");let mut cost_open=vec![];if let Ok(nodes)=root.query_selector_all("[data-cost-group][open]"){for i in 0..nodes.length(){if let Some(node)=nodes.item(i){if let Ok(e)=node.dyn_into::<Element>(){if let Some(key)=e.get_attribute("data-cost-group"){cost_open.push(key);}}}}}let extra_open=["exterior","outdoor","windows","panels","surfaces","room-finishes"].map(|key|(key,expanded(&format!("[data-section={}]",key))));let scroll=root.query_selector(".control-body").ok().flatten().map(|e|e.scroll_top()).unwrap_or(0);root.set_inner_html(value);for(selector,open)in[(".millwork-controls",millwork_open),(".millwork-library",library_open),(".source-card",source_open),("[data-section=colors]",colors_open),("[data-section=roof]",roof_open)]{if open{if let Ok(Some(e))=root.query_selector(selector){e.set_attribute("open","").ok();}}}for key in cost_open{if let Ok(nodes)=root.query_selector_all("[data-cost-group]"){for i in 0..nodes.length(){if let Some(node)=nodes.item(i){if let Ok(e)=node.dyn_into::<Element>(){if e.get_attribute("data-cost-group").as_deref()==Some(&key){e.set_attribute("open","").ok();}}}}}}for(key,open)in extra_open{if open{if let Ok(Some(e))=root.query_selector(&format!("[data-section={}]",key)){e.set_attribute("open","").ok();}}}if let Ok(Some(body))=root.query_selector(".control-body"){body.set_scroll_top(scroll);}}}
pub fn esc(s:&str)->String{s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;").replace('\'',"&#39;")}
fn money(v:f64)->String{let text=format!("{:.2}",v);let mut parts=text.split('.');let whole=parts.next().unwrap();let mut out=String::new();for(i,ch)in whole.chars().enumerate(){if i>0&&(whole.len()-i)%3==0{out.push(',')}out.push(ch)}format!("${}.{}",out,parts.next().unwrap_or("00"))}
fn selected(a:&str,b:&str)->&'static str{if a==b{"selected"}else{""}}fn checked(b:bool)->&'static str{if b{"checked"}else{""}}
fn garage_plan(m:&Value)->String{let g=&m["garage"];if !g.is_object(){return String::new()}let(x,z)=(n(g,"x"),n(g,"z"));let mut out=format!("<g class=garage-plan aria-label=\"{} two-car garage\"><rect x={} y={} width=24 height=24 fill=\"#2c3934\"/><text x={} y={} text-anchor=middle fill=\"#e8cd6e\" font-size=1.1>Two-car garage</text><text x={} y={} text-anchor=middle fill=\"#bfc8b7\" font-size=.9>24 × 24 ft · 576 sq ft</text>",s(g,"kind"),x,z,x+12.,z+10.,x+12.,z+12.);for bx in [x+2.,x+13.]{out.push_str(&format!("<rect x={} y={} width=9 height=18 rx=.8 fill=none stroke=\"#8d9e85\" stroke-dasharray=\".3 .3\" stroke-width=.06/>",bx,z+3.));}for wall in g["walls"].as_array().unwrap(){let along=s(wall,"axis")=="x";let(wx,wz,len)=(n(wall,"x"),n(wall,"z"),n(wall,"length"));let point=|a:f64|(wx+if along{a}else{0.},wz+if along{0.}else{a});let mut cursor=0.;for o in wall["openings"].as_array().unwrap().iter().chain(std::iter::once(&json!({"at":len,"width":0.}))){let a=n(o,"at");let(x1,z1)=point(cursor);let(x2,z2)=point(a);if a>cursor{out.push_str(&format!("<line x1={} y1={} x2={} y2={} stroke=\"#c7cbbc\" stroke-width=.28/>",x1,z1,x2,z2));}if n(o,"width")>0.{let(x1,z1)=point(a);let(x2,z2)=point(a+n(o,"width"));out.push_str(&format!("<line x1={} y1={} x2={} y2={} stroke=\"{}\" stroke-width=.15><title>{}</title></line>",x1,z1,x2,z2,if s(o,"kind")=="window"{"#83c7e9"}else{"#de9865"},if s(o,"id")=="G-OVERHEAD"{"16 × 7 ft overhead door"}else{"Garage opening"}));}cursor=a+n(o,"width");}}out.push_str("</g>");out}
fn opts(names:&[String],value:&str)->String{names.iter().map(|name|format!("<option value=\"{}\" {}>{}</option>",esc(name),selected(name,value),esc(name))).collect()}
fn select(key:&str,label:&str,names:&[String],value:&str)->String{format!("<label class=field>{}<select aria-label=\"{}\" data-field=\"{}\">{}</select></label>",label,esc(label),key,opts(names,value))}
fn choices(key:&str)->Vec<String>{catalog()["options"][key].as_array().unwrap().iter().filter_map(|v|v.as_str().map(str::to_string)).collect()}
fn strings(a:&[&str])->Vec<String>{a.iter().map(|s|s.to_string()).collect()}
fn number(id:&str,label:&str,value:f64,min:f64,max:f64)->String{format!("<label class=field>{}<input id=\"{}\" aria-label=\"{}\" type=number min={} max={} step=0.01 value=\"{}\"></label>",label,id,label,min,max,value)}
fn btn(action:&str,text:&str,class:&str)->String{format!("<button class=\"button {}\" data-action=\"{}\">{}</button>",class,action,text)}
