fn trim_controls(a:&State)->String{let t=&a.m["trimPackage"];let mut out=format!("<div class=trim-finish-preview><div class=trim-wood-preview role=img aria-label=\"{} wood grain\"></div><div><strong>{}</strong><span>{:.1} in base · {:.1} in casing</span></div></div><fieldset class=trim-size-control><legend>Trim size</legend><div class=trim-size-buttons>",esc(s(t,"finish")),esc(s(t,"finish")),n(t,"baseHeight")*12.,n(t,"casingWidth")*12.);for size in["Normal","Oversized"]{out.push_str(&format!("<button data-action=trim-size data-value={} aria-pressed=\"{}\" class=\"{}\">{}</button>",size,a.c.trim_size==size,if a.c.trim_size==size{"active"}else{""},size));}out.push_str("</div></fieldset><details class=millwork-controls><summary>Customize profiles · 100 original types</summary><p>Sealed wood throughout. Each part uses a suitable section from Rockwell’s 1904 catalog. Normal sizes suit the package; Oversized scales the parts by 1.5.</p>");for(role,label)in[("base","Baseboard"),("cap","Optional base cap"),("shoe","Optional base shoe"),("casing","Interior entrances"),("crown","Interior crown"),("corner","Interior corner trim"),("window","Exterior window & door surrounds"),("hood","Exterior drip cap"),("cornice","Eave / rake cornice"),("frieze","Under-overhang frieze")]{let part=&t["parts"][role];out.push_str(&format!("<label class=field>{}<select data-trim-role=\"{}\" aria-label=\"{} profile\"><option value=none {}>None</option>",label,role,label,if part.is_null(){"selected"}else{""}));for profile in trim::profiles().iter().filter(|p|trim::part_allowed(role,p)){out.push_str(&format!("<option value=\"{}\" {}>{} · {:.2} in</option>",s(profile,"id"),selected(s(profile,"id"),s(part,"id")),esc(s(profile,"name")),n(profile,"widthInches")));}out.push_str("</select></label>");if !part.is_null(){out.push_str(&format!("<div class=millwork-selected><img loading=lazy src=\"{}\" alt=\"Original {} section\"><div><strong>No. {}</strong><span>Installed {:.2} in high × {:.2} in projection</span><span>Stock {:.2} × {:.2} in · page {:.0}</span></div></div>",esc(s(part,"thumbnail")),esc(s(part,"name")),n(part,"catalogNumber"),n(part,"installedHeightInches"),n(part,"installedProjectionInches"),n(part,"widthInches"),n(part,"depthInches"),n(part,"printedPage")));}}
out.push_str("<p class=muted>Section contours are traced from the original drawings. Spring dimensions and some fractions are approximate; use the source catalog and shop drawings for fabrication.</p><a target=_blank rel=noopener href=https://archive.org/details/millworkcatalogu00rock>Rockwell Millwork Catalogue · 1904</a><details class=millwork-library><summary>Browse all 100 source sections</summary><div class=millwork-gallery>");for p in trim::profiles(){out.push_str(&format!("<figure><a target=_blank rel=noopener href=\"{}\"><img loading=lazy src=\"{}\" alt=\"{}\"></a><figcaption>No. {:.0}<span>{}</span></figcaption></figure>",esc(s(p,"sourceThumbnail")),esc(s(p,"thumbnail")),esc(s(p,"name")),n(p,"catalogNumber"),esc(s(p,"role"))));}out.push_str("</div></details></details>");out}

pub fn preview_placement(input:&str)->String{editor::placement(input)}

fn circulation_html(a:&State)->String{let access=&a.m["accessibility"];let issues=access["allIssues"].as_array().or_else(||access["issues"].as_array());let mut out=String::from("<section class=circulation-info><strong>Clear circulation</strong><p>36 in route target · 60 in turning target · 5 × 5 ft clear stair approaches. Blue areas in the editor stay clear of furniture.</p>");if let Some(issues)=issues{for issue in issues{out.push_str(&format!("<p>{}</p>",esc(issue.as_str().unwrap_or(""))));}}out.push_str("<p>Planning checks only. Verify door products, bathroom clearances, thresholds and step-free access with your designer. Stairs alone do not make the upper story wheelchair accessible.</p><a href=https://www.access-board.gov/ada/chapter/ch04/ target=_blank rel=noopener>U.S. Access Board · clearance guidance</a></section>");out}

fn panel_controls(a:&State)->String{
 let mut out=String::from("<details class=control-group data-section=panels><summary>Universal Frame panel assemblies</summary><p class=muted>Factory panel defaults. The standard precut plus three plates is 97-1/8 in; 8, 9 and 10 ft custom walls use cut stock.</p>");
 for panel in a.m["panelAssemblies"].as_array().into_iter().flatten(){out.push_str(&format!("<details class=assembly-card><summary>{}</summary><p>{}</p><ol>",esc(s(panel,"name")),esc(s(panel,"module"))));for layer in panel["layers"].as_array().into_iter().flatten(){out.push_str(&format!("<li>{}</li>",esc(layer.as_str().unwrap_or(""))));}out.push_str("</ol></details>");}
 out.push_str(&select("roofInsulation","Roof batt package",&strings(&["R-49","R-38 HD + R-11"]),&a.c.roof_insulation));
 for (field,label,value) in [("interiorSound","Bedroom / bath R-13 sound batts",a.c.interior_sound),("upperSound","Upper-floor R-19 sound batts",a.c.upper_sound)]{out.push_str(&format!("<label class=check><input type=checkbox data-field={} {}>{}</label>",field,checked(value),label));}
 out.push_str("<p class=muted>Required R-value and installed product performance are separate. Header selections and I-joist series remain subject to load and manufacturer review.</p></details>");out
}
fn surface_controls(a:&State)->String{
 let mut out=String::from("<details class=control-group data-section=surfaces><summary>Tile walls &amp; upload a pattern</summary><p class=muted>Tiles cover the chosen room group. Uploaded patterns repeat at a real-world size and travel with downloaded design JSON.</p>");
 let mut names=vec!["None".to_string()];names.extend(surfaces::tiles().as_array().unwrap().iter().map(|t|s(t,"name").to_string()));
 for (key,label) in [("bedroom","Bedroom walls"),("general","Rest of house walls")]{let value=a.c.wall_tiles.get(key).map(String::as_str).unwrap_or("None");out.push_str(&select(key,&format!("{} · tile",label),&names,value).replace(&format!("data-field=\"{}\"",key),&format!("data-wall-tile=\"{}\"",key)));}
 for (key,label) in [("bedroom","Bedroom walls"),("general","Rest of house walls"),("floor","All house floors")]{let pattern=a.c.custom_textures.get(key);out.push_str(&format!("<div class=texture-control><strong>{}</strong><label class=field>Pattern repeat · ft<input type=number min=.25 max=16 step=.25 data-texture-repeat=\"{}\" data-pattern-repeat=\"{}\" value=\"{}\"></label><label class=texture-upload>Upload JPEG / PNG / WebP<input type=file accept=\"image/jpeg,image/png,image/webp\" data-texture-upload=\"{}\"></label>",label,key,key,pattern.map_or(2.,|p|p.repeat_feet),key));if let Some(p)=pattern{out.push_str(&format!("<div class=texture-current><img src=\"{}\" alt=\"Uploaded repeating pattern\"><span>{}</span><button class=text data-action=texture-remove data-value={}>Remove</button></div>",esc(&p.data_url),esc(&p.name),key));}out.push_str("</div>");}
 out.push_str("<p class=muted>Up to 12 MB input; resized and stored as bounded JPEG. A tile selection replaces the custom wall pattern in that group.</p></details>");out
}
pub fn texture(input:&str){
 let Ok(v)=serde_json::from_str::<Value>(input)else{return};let key=s(&v,"target");if !["bedroom","general","floor"].contains(&key){return}
 let Ok(pattern)=serde_json::from_value::<surfaces::TexturePattern>(v["pattern"].clone())else{return};
 STATE.with(|cell|{let mut a=cell.borrow_mut();a.c.custom_textures.insert(key.into(),pattern);if key!="floor"{a.c.wall_tiles.remove(key);if key=="bedroom"{a.c.bedroom_wallpaper="None".into();}else{a.c.wallpaper="None".into();}}changed(&mut a);});render(true);
}

fn room_finish_controls(a:&State)->String{
 let mut out=String::from("<details class=control-group data-section=room-finishes><summary>Wallpaper each room individually</summary><p class=muted>Use a house default or choose a different pattern for each room. Individual choices replace that room's group tile or uploaded wall pattern. Choose None for painted drywall.</p>");
 let levels=a.m["levels"].as_array().map(|ls|ls.iter().collect::<Vec<_>>()).unwrap_or_else(||vec![&a.m]);let mut names=vec!["House default".to_string()];names.extend(choices("wallpaper"));
 for level in levels{let floor=n(level,"floorIndex")as usize;out.push_str(&format!("<h4>{}</h4>",if floor==0{"Main floor"}else{"Upper floor"}));for room in level["finishRooms"].as_array().into_iter().flatten(){if s(room,"type")=="stairs"{continue}let id=s(room,"id");let value=a.c.room_wallpapers.get(id).map(String::as_str).unwrap_or("House default");let label=format!("{} · wallpaper",s(room,"name"));out.push_str(&select(id,&esc(&label),&names,value).replace(&format!("data-field=\"{}\"",id),&format!("data-room-wallpaper=\"{}\"",id)));}}
 out.push_str("<p class=muted>In blank slate, full separating walls define individual rooms; partial walls remain part of the same space.</p></details>");out
}
fn garage_entry_controls(a:&State)->String{
 if a.c.garage!="Attached"{return String::new()}let ground=if a.c.stories==2{&a.m["levels"][0]}else{&a.m};
 for w in ground["walls"].as_array().into_iter().flatten(){if let Some(o)=w["openings"].as_array().unwrap().iter().find(|o|s(o,"id")=="G-HOUSE-DOOR"){let center=n(w,"z")+n(o,"at")+n(o,"width")/2.;return format!("<label class=field>House–garage door center · ft from house front<input type=number data-garage-entry aria-label=\"House–garage door center\" min=0 max=100 step=.25 value=\"{:.3}\"></label><p class=muted>Move the connecting door along the shared wall. You can also click the door in 3D and edit its Start position. The garage stays in place.</p>",center)}}
 "<p class=muted>No shared doorway fits this layout. Choose the other garage side or revise the adjoining room.</p>".into()
}
